#include <stdio.h>

int main(void) {
    int a[] = {1, 3, -1, -3, 5, 3, 6, 7};
    int n = 8, k = 3;
    int q[8], head = 0, tail = 0;
    printf("数组:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n窗口大小 k=%d 的最大值序列:", k);
    for (int i = 0; i < n; i++) {
        while (tail > head && a[q[tail - 1]] <= a[i]) tail--;  /* 队尾淘汰更小者 */
        q[tail++] = i;
        if (q[head] <= i - k) head++;                          /* 队首过期 */
        if (i >= k - 1) printf(" %d", a[q[head]]);
    }
    printf("\n");
    return 0;
}
